/*
================================================================================
  FILE:   fb-styles (shared CSS)
  PATH:   scripts/fb-styles.css
  --------------------------------------------------------------------------------
  Canonical stylesheet for every Fishbowl BI report. Deployed by saving the
  contents as a Fishbowl Style named "fb-styles" and injecting it into each
  report via Fishbowl's Style directive — using the syntax described in
  scripts/fb-lib.js's "DROP-DOWN DRAWER" section, but with the Style verb
  and the name "fb-styles". (We never write the literal placeholder text
  here because the result of this file's expansion would inline it into
  the host report, producing a duplicate mention that breaks Fishbowl's
  single-pass directive substitution.) Owns design tokens, the
  .hdr-btn / .btn families, modal-* chrome, fb-drawer, toasts, app-tooltip,
  scrollbar, spinner, shared form/badge utilities, AND (2026-07) the full
  Workspace chrome promoted from the v1.2 dashboards: .topbar/.tabs,
  .ps-btn, .filterbar/.fchip/.fdrop, .spill, the icon-chip .kpi-tile, the
  two table tiers (.rpt-table report / .tbl-wrap dashboard), .row-link,
  the .ms-* multi-select skin, and .b* status badges — promoting these out
  of each report so a single edit re-themes the whole report family.
================================================================================
*/

/* 1. TOKENS — Fishbowl Global Brand Guidelines (Media Kit ▸ Brand
   Guidelines ▸ Global Brand Guidelines.pdf, rev 1/09/2023).
   Neutrals = brand slate family · dark chrome = brand navy #0B3140 ·
   10px corner radius · #101010-based shadows · brand accent pairs.
   UI BLUE DECISION (2026-07-10): the brand core Fishbowl Blue #083CF3
   (PMS 2728C) is too intense for interface work — per the guide it's
   used "sparingly" (logo, print). The working UI blue is the classic
   #2d9cdb family. Do NOT reintroduce #083CF3 into component styles.
   Hover/pressed blues and the semantic success/warning/negative are
   DERIVED — the brand palette defines no interaction states and no
   functional green/red. Component mockup:
   Other_NOT_FOR_PRODUCTION/FB_Brand_Mockup.htm */
:root {
    /* Legacy aliases — every pre-v1.2 report styles off these two. */
    --color-primary: #2d9cdb;
    --color-primary-dark: #1e7bb4;

    /* UI blue + derived interaction states */
    --fb-blue: #2d9cdb; --fb-blue-accent: #1e7bb4;
    --fb-blue-hover: #4FB0E4; --fb-blue-pressed: #176C9E;

    /* Semantics (derived — see note above) */
    --fb-success: #1B7A46; --fb-warning: #B26A14;
    --fb-negative: #C43046; --fb-neutral: #506872;

    /* Surfaces + borders */
    --bg-primary: #FFFFFF; --bg-1: #F7F7F7; --bg-2: #EBEEED;
    --bg-3: #E3E3E3; --bg-4: #C6D0D4;
    --border: #E3E3E3; --border-strong: #C6D0D4;

    /* Dark chrome (table heads, menus, drawer bands) */
    --menu-bg: #0B3140; --menu-bg-2: #0E3646;

    /* Text */
    --c-primary: #101010; --c-secondary: #506872;
    --c-tertiary: #8FA1A7;

    /* Link blue — interactive TEXT (row-links, order #s, action links).
       Same family as the UI blue; hover darkens to the classic pair. */
    --link: #2d9cdb; --link-hover: #1e7bb4;

    /* Selected / tint states */
    --tint-blue: #DEEAF4; --tint-blue-2: #CBE5FB;

    /* Brand accent pairs (color / pill-bg / on-tint text) */
    --acc-purple: #845EEB; --acc-purple-bg: #D9CEF7; --acc-purple-con: #3D2380;
    --acc-maroon: #802842; --acc-maroon-bg: #F0D7DD; --acc-maroon-con: #5E1D30;
    --acc-orange: #F69133; --acc-orange-bg: #F5E7DD; --acc-orange-con: #8A4E10;
    --acc-yellow: #F7C23A; --acc-yellow-bg: #FBEDC4; --acc-yellow-con: #7A5A08;
    --acc-sage:   #DBE8E1; --acc-sage-con:  #1B7A46;

    /* Type — brand fonts (Cooper Light BT / Milligram Text) are licensed;
       Inter is the standing web fallback. Reports that want Space Mono
       must still load it themselves (Google Fonts link). */
    --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    --mono: 'Space Mono', ui-monospace, 'Consolas', monospace;

    /* Geometry + shadows (PDF p.40–41) */
    --r-btn: 6px; --r-card: 10px; --r-modal: 12px; --r-pill: 999px;
    --sh1: 0 1px 3px rgba(16,16,16,.10);
    --sh2: 0 4px 12px rgba(16,16,16,.13);
    --sh3: 0 12px 32px rgba(16,16,16,.24);
}

/* 2. RESET + BASE */
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
    font-family: var(--font);
    font-size: 13px; color: #101010; background: #F7F7F7;
}
.mono { font-family: var(--mono); }

/* 3. TYPOGRAPHY */
h1 { font-size: 16px; font-weight: 700; color: #101010; }
h2 { font-size: 14px; font-weight: 600; color: #101010; }
h3 { font-size: 14px; font-weight: 600; color: #101010; }
h4 { font-size: 13px; font-weight: 700; color: #101010; margin-bottom: 8px; }
h5 { font-size: 12px; font-weight: 600; color: #101010; }
h6 { font-size: 12px; font-weight: 600; color: #101010; margin-bottom: 6px; }
.subtitle { font-size: 12px; color: #506872; margin-bottom: 12px; }

/* 4. HEADER + .hdr-btn family */
header {
    position: sticky; top: 0; z-index: 50;
    background: #fff; border-bottom: 1px solid #E3E3E3;
    box-shadow: 0 1px 2px rgba(0,0,0,0.04);
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 20px; height: 56px;
    flex: 0 0 56px; min-height: 56px;
}
header h1 { font-size: 16px; font-weight: 700; color: #101010; margin: 0; line-height: 1.15; }
#statusLine { font-size: 12px; color: #8FA1A7; line-height: 1.15; margin: 2px 0 0; }
.hdr-actions { display: flex; align-items: center; gap: 8px; }
/* .hdr-btn vertical padding was 6px; reduced to 4px so the button
   height matches the view-mode dropdown wrapper (which uses padding:
   4px 10px) in the summary reports. The button-group rows now sit on
   a single visual baseline. */
.hdr-btn {
    display: flex; align-items: center; gap: 5px; padding: 4px 10px; border-radius: 8px;
    font-size: 12px; font-weight: 500; border: 1px solid #E3E3E3; background: #fff;
    color: #506872; cursor: pointer; transition: all 0.15s; white-space: nowrap; font-family: inherit;
    line-height: 1.4;
}
.hdr-btn:hover { background: #F7F7F7; border-color: #C6D0D4; }
.hdr-btn svg { width: 15px; height: 15px; flex-shrink: 0; }
/* Icon-only buttons (e.g. the Settings cog) keep a slightly larger
   square padding so they don't look pinched next to the bigger text
   buttons. */
.hdr-btn-icon { padding: 5px; }
.hdr-btn.active { background: #DEEAF4; border-color: #CBE5FB; color: var(--color-primary-dark); }
/* Primary (filled) header button — used for the main action in a header
   group, e.g. the Excel half of an export pair. */
.hdr-btn-primary { background: var(--color-primary); border-color: var(--color-primary); color: #fff; }
.hdr-btn-primary:hover { background: var(--color-primary-dark); border-color: var(--color-primary-dark); }
.hdr-btn[disabled] { opacity: 0.55; cursor: progress; }
/* SPLIT-BTN — two or more .hdr-btn joined into one segmented control.
   Used for the Excel / CSV export pair: both formats stay one click away,
   with the primary variant marking the default. Radii collapse to the
   outer edges and inner left borders are dropped so the neighbouring
   button's right border acts as the single divider. */
.split-btn { display: inline-flex; }
.split-btn > .hdr-btn { border-radius: 0; }
.split-btn > .hdr-btn:first-child { border-top-left-radius: 8px; border-bottom-left-radius: 8px; }
.split-btn > .hdr-btn:last-child  { border-top-right-radius: 8px; border-bottom-right-radius: 8px; }
.split-btn > .hdr-btn + .hdr-btn  { border-left: none; }

/* 5. BUTTONS */
.btn {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 7px 12px; font-size: 12px; font-weight: 600;
    border: 1px solid #C6D0D4; background: #fff; color: #415157;
    border-radius: 7px; cursor: pointer; transition: all 0.15s;
    text-decoration: none; line-height: 1.4; font-family: inherit;
}
.btn:hover { background: #EBEEED; }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }
.btn-primary { background: var(--color-primary); color: #fff; border-color: var(--color-primary); }
.btn-primary:hover { background: var(--color-primary-dark); border-color: var(--color-primary-dark); }
.btn-outline-primary { color: var(--color-primary); border-color: #C6D0D4; background: #fff; }
.btn-outline-primary:hover { background: var(--color-primary); border-color: var(--color-primary); color: #fff; }
.btn-success { background: #1B7A46; color: #fff; border-color: #1B7A46; }
.btn-success:hover { background: #156138; border-color: #156138; }
.btn-outline-success { color: #156138; border-color: #C6D0D4; background: #fff; }
.btn-outline-success:hover { background: #1B7A46; border-color: #1B7A46; color: #fff; }
.btn-danger { background: #C43046; color: #fff; border-color: #A32439; }
.btn-danger:hover:not(:disabled) { background: #A32439; border-color: #8A1E30; }
.btn-sm { padding: 4px 9px; font-size: 11px; border-radius: 6px; }
.btn-lg { padding: 8px 14px; font-size: 13px; }

/* 6. FORMS */
input[type="text"], input[type="file"], input[type="number"], input[type="date"],
select, .form-control, .form-select {
    padding: 7px 9px; font-size: 13px; border: 1px solid #C6D0D4; border-radius: 6px;
    color: #101010; background: #fff; font-family: inherit;
}
input:focus, select:focus, .form-control:focus, .form-select:focus {
    outline: none; border-color: var(--color-primary); box-shadow: 0 0 0 3px rgba(45,156,219,0.15);
}
input[type="checkbox"] { cursor: pointer; width: auto; }
label { font-size: 12px; color: #415157; font-weight: 500; }
.form-select-sm, .form-control-sm { padding: 5px 8px; font-size: 12px; }
.form-check { display: flex; align-items: center; gap: 8px; }
.form-check-input { margin: 0; }
.form-check-label { font-size: 12px; color: #415157; font-weight: 500; }

/* 7. ALERTS */
.alert { border-radius: 7px; border: 1px solid; font-size: 12px; padding: 9px 12px; margin-bottom: 10px; }
.alert-info    { background: #DEEAF4; border-color: #CBE5FB; color: #1e7bb4; }
.alert-warning { background: #F5E7DD; border-color: #EBC49B; color: #8A4E10; }
.alert-danger  { background: #F0D7DD; border-color: #D9A4B2; color: #8A1E30; }
.alert-success { background: #DBE8E1; border-color: #A9CDBA; color: #1B7A46; }

/* 8. BADGES */
.stat-badge {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 5px 11px; border-radius: 999px;
    font-size: 11px; font-weight: 600; border: 1px solid; line-height: 1.4;
}
.stat-badge.total   { background: #DEEAF4; border-color: #CBE5FB; color: #1e7bb4; }
.stat-badge.ready   { background: #DBE8E1; border-color: #A9CDBA; color: #1B7A46; }
.stat-badge.issues  { background: #F5E7DD; border-color: #EBC49B; color: #8A4E10; }
.stat-badge.missing { background: #F0D7DD; border-color: #D9A4B2; color: #8A1E30; }
.stat-badge.info    { background: #EBEEED; border-color: #C6D0D4; color: #506872; }
.stat-number { font-weight: 800; }
.stat-label  { opacity: 0.85; }
.stat-badge.kpi {
    cursor: pointer; transition: background 0.12s, border-color 0.12s;
    user-select: none;
}
.stat-badge.kpi:hover { background: #E8C6D0; }
.stat-badge.kpi.active {
    background: #C43046; color: #fff; border-color: #8A1E30;
    box-shadow: 0 1px 3px rgba(196, 48, 70, 0.35);
}
.stat-badge.kpi.active .stat-label,
.stat-badge.kpi.active .stat-number { color: #fff; opacity: 1; }
.stat-badge.kpi .kpi-x {
    display: inline-block; margin-left: 4px; font-size: 13px;
    line-height: 1; opacity: 0;
}
.stat-badge.kpi.active .kpi-x { opacity: 0.9; }

/* 9. CONFIG GROUPS */
.config-group {
    margin-bottom: 14px; padding: 12px; background: #F7F7F7;
    border-radius: 8px; border: 1px solid #E3E3E3;
}
.config-group h5 {
    color: #101010; font-size: 12px; font-weight: 700; margin-bottom: 8px;
    display: flex; align-items: center; gap: 6px;
    text-transform: uppercase; letter-spacing: 0.03em;
}
.config-item { margin-bottom: 10px; }
.config-item label {
    display: block; font-size: 11px; font-weight: 600;
    color: #506872; margin-bottom: 4px;
}
.config-item .form-select, .config-item .form-control { width: 100%; }

/* 10. INFO BOXES */
.info-box {
    padding: 11px 12px; background: #DEEAF4;
    border-left: 3px solid var(--color-primary); border-radius: 7px;
    margin-bottom: 12px; font-size: 12px; color: #415157;
}
.info-box ul { margin-bottom: 0; padding-left: 18px; }
.info-box li { margin-bottom: 4px; }
.info-box h6 { font-size: 12px; margin-bottom: 6px; }
.info-box p  { margin: 4px 0; }

/* 11. DRAWERS — header drop-down panels (settings / help / filters).
   OVERLAY behaviour: the drawer is fixed, drops down from under the header,
   and floats IN FRONT of the page (it no longer sits in the flex flow, so it
   never pushes the content down). A shared scrim (.fb-drawer-scrim, injected
   once by fb-lib) greys the page behind it and closes it on click.
   --fb-drawer-top is set by fb-lib at open time from the live header/topbar
   height so the panel + scrim start just below the header (which stays clear
   and clickable). Sizes divide by var(--ps-zoom,1) so they still fill under
   Production Scheduling's body-zoom (a no-op = 1 on pages that don't set it). */
.fb-drawer {
    position: fixed; top: var(--fb-drawer-top, 56px); left: 0;
    width: calc(100vw / var(--ps-zoom, 1));
    max-height: calc((100vh - var(--fb-drawer-top, 56px)) / var(--ps-zoom, 1));
    background: #F7F7F7; border-bottom: 1px solid #E3E3E3;
    box-shadow: 0 10px 24px -10px rgba(16, 16, 16, 0.28);
    display: none; flex-direction: column; z-index: 10001;
}
.fb-drawer.open { display: flex; }
/* Full-page scrim behind an open drawer (below the header). fb-lib toggles
   `.open` and wires a click-to-close handler. */
.fb-drawer-scrim {
    position: fixed; top: var(--fb-drawer-top, 56px); left: 0;
    width: calc(100vw / var(--ps-zoom, 1));
    height: calc((100vh - var(--fb-drawer-top, 56px)) / var(--ps-zoom, 1));
    background: rgba(16, 16, 16, 0.35);
    z-index: 10000; display: none;
}
.fb-drawer-scrim.open { display: block; }
/* Drawer band = brand navy (mockup §5), not the primary blue — the
   guidelines call for the blue to be used sparingly. */
.fb-drawer-head {
    display: flex; justify-content: space-between; align-items: center;
    padding: 10px 18px; border-bottom: 1px solid #E3E3E3;
    background: var(--menu-bg); color: #fff; flex-shrink: 0;
}
.fb-drawer-head h2 { margin: 0; font-size: 14px; color: #fff; font-weight: 700; }
.fb-drawer-close {
    background: transparent; border: none; font-size: 22px; cursor: pointer;
    color: #fff; line-height: 1; opacity: 0.9; padding: 0 6px;
}
.fb-drawer-close:hover { opacity: 1; }
/* Body flex-fills the capped drawer and scrolls; head/foot stay pinned. */
.fb-drawer-body { padding: 14px 18px; overflow-y: auto; flex: 1 1 auto; min-height: 0; }
.fb-drawer-foot {
    padding: 10px 18px; border-top: 1px solid #E3E3E3; background: #fff;
    display: flex; gap: 8px; justify-content: space-between; align-items: center;
    flex-wrap: wrap; flex-shrink: 0;
}
.ds-label {
    display: block; font-weight: 700; font-size: 11px;
    text-transform: uppercase; letter-spacing: 0.04em;
    color: #506872; margin-bottom: 8px;
}
.ds-btn {
    padding: 7px 13px; font-size: 12px; border-radius: 7px;
    border: 1px solid #C6D0D4; background: #fff; cursor: pointer;
    font-family: inherit; font-weight: 600; color: #415157;
}
.ds-btn:hover { background: #EBEEED; }
.ds-btn-primary { background: var(--color-primary); color: #fff; border-color: var(--color-primary); }
.ds-btn-primary:hover { background: var(--color-primary-dark); }
.ds-admin { border-top: 1px dashed #C6D0D4; padding-top: 14px; margin-top: 6px; }
.ds-btn-admin {
    display: inline-block; margin-right: 6px; margin-bottom: 6px;
    background: #F5E7DD; border-color: #F69133; color: #8A4E10;
}
.ds-lock-badge {
    background: #F5E7DD; color: #8A4E10; border: 1px solid #F69133;
    padding: 7px 10px; border-radius: 7px; font-size: 12px; margin-bottom: 14px;
}
.ds-grid { display: flex; flex-wrap: wrap; gap: 12px; align-items: flex-start; }
.ds-grid > .config-group { flex: 1 1 240px; margin-bottom: 0; }

/* 12. MODALS */
.modal-overlay {
    position: fixed; inset: 0; background: rgba(0,0,0,0.5); z-index: 1010;
    display: none; align-items: center; justify-content: center; padding: 20px;
}
.modal-overlay.open { display: flex; }
.modal-card {
    background: #fff; border-radius: var(--r-modal); width: 100%; max-width: 900px;
    max-height: 90vh; display: flex; flex-direction: column;
    box-shadow: 0 25px 50px -12px rgba(16,16,16,0.25);
}
/* Modal header = white + slim (mockup §5). Was a solid primary-blue band
   with white text — that painted every drilldown/picker header bright
   blue and forced local overrides (e.g. Sales_Dashboard_v1.2). Reports
   whose modal-head children assume white-on-blue need a re-check. */
.modal-head {
    display: flex; align-items: center; justify-content: space-between;
    padding: 10px 16px; border-bottom: 1px solid #E3E3E3;
    background: #fff; color: var(--c-primary); border-radius: var(--r-modal) var(--r-modal) 0 0;
}
.modal-head h3 { margin: 0; color: var(--c-primary); font-size: 14px; font-weight: 800; }
.modal-body { padding: 16px 20px; overflow-y: auto; flex: 1; }
.modal-foot {
    display: flex; align-items: center; justify-content: space-between;
    padding: 12px 20px; border-top: 1px solid #E3E3E3; gap: 8px; flex-wrap: wrap;
}
.modal-foot .left-grp, .modal-foot .right-grp { display: flex; gap: 8px; }

/* 13. TOOLTIPS */
.app-tooltip {
    position: fixed;
    background: rgba(11, 49, 64, 0.96);
    color: #fff;
    padding: 9px 12px;
    border-radius: 8px;
    font-size: 11px;
    line-height: 1.5;
    pointer-events: none;
    z-index: 10000;
    box-shadow: 0 10px 28px rgba(0,0,0,0.32);
    opacity: 0;
    transition: opacity 0.15s ease;
    max-width: 320px;
    white-space: pre-line;
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    font-weight: 400;
    text-transform: none;
    letter-spacing: 0;
}
.app-tooltip.show { opacity: 1; }
.app-tooltip .tt-title {
    color: #fff; font-weight: 700; font-size: 12px;
    display: block; margin-bottom: 4px;
}
.app-tooltip .tt-req {
    color: #f87171; font-weight: 700; margin-left: 4px;
}
.app-tooltip .tt-meta {
    display: block; margin-top: 6px; padding-top: 6px;
    border-top: 1px solid rgba(148, 163, 184, 0.3);
    color: #8FA1A7; font-size: 10.5px;
}
.app-tooltip .tt-meta .lbl { color: #C6D0D4; font-weight: 600; }
.app-tooltip .tt-desc {
    color: #E3E3E3; font-weight: 400; white-space: pre-line;
}

/* 14. TOASTS */
.toast-container {
    position: fixed; bottom: 1rem; right: 1rem; top: 1rem; z-index: 9999;
    display: flex; flex-direction: column; justify-content: flex-end;
    gap: 0.5rem; overflow-y: auto; pointer-events: none;
}
.toast-container .toast { pointer-events: auto; }
.toast {
    min-width: 280px; max-width: 380px; padding: 12px 14px;
    background: #fff; border-radius: 10px;
    box-shadow: 0 10px 25px -5px rgba(0,0,0,0.2);
    border-left: 4px solid #2d9cdb;
    display: flex; align-items: flex-start; gap: 10px;
    animation: toastSlideIn 0.25s ease-out;
    transition: opacity 0.25s ease;
}
.toast.success { border-left-color: #1B7A46; }
.toast.error   { border-left-color: #C43046; }
.toast.warn    { border-left-color: #F69133; }
.toast.info    { border-left-color: var(--color-primary); }
.toast .toast-icon { font-size: 15px; line-height: 1.3; }
.toast.success .toast-icon { color: #1B7A46; }
.toast.error   .toast-icon { color: #C43046; }
.toast.warn    .toast-icon { color: #F69133; }
.toast.info    .toast-icon { color: var(--color-primary); }
.toast .toast-msg {
    font-size: 12.5px; color: #415157; font-weight: 500;
    flex: 1; min-width: 0; line-height: 1.4;
    word-break: break-word; overflow-wrap: anywhere;
    max-height: 40vh; overflow-y: auto;
}
.toast .toast-x {
    background: none; border: none; color: #8FA1A7; cursor: pointer;
    font-size: 18px; line-height: 1; padding: 2px 4px;
    margin: -2px -4px 0 0; flex-shrink: 0; align-self: flex-start;
}
.toast .toast-x:hover { color: #506872; }
@keyframes toastSlideIn {
    from { transform: translateX(400px); opacity: 0; }
    to   { transform: translateX(0); opacity: 1; }
}

/* 15. FILTERS DROPDOWN */
.filters-dropdown { position: relative; display: inline-block; }
.filters-popover {
    position: absolute;
    top: calc(100% + 4px);
    right: 0;
    background: #fff;
    border: 1px solid #E3E3E3;
    border-radius: 8px;
    box-shadow: 0 10px 25px -5px rgba(0,0,0,0.18);
    padding: 10px 12px;
    z-index: 100;
    min-width: 230px;
    display: none;
}
.filters-dropdown.open .filters-popover { display: block; }
.filters-popover .form-check {
    display: flex; align-items: center;
    padding: 5px 4px; border-radius: 5px;
    cursor: pointer;
}
.filters-popover .form-check:hover { background: #EBEEED; }
.filters-popover .form-check + .form-check { margin-top: 1px; }
.btn.filters-active {
    border-color: var(--color-primary);
    background: #DEEAF4;
    color: var(--color-primary-dark);
}

/* 16. COLUMNS PICKER DROPDOWN */
.columns-dropdown { position: relative; display: inline-block; }
.columns-popover {
    position: absolute; top: calc(100% + 4px); right: 0;
    background: #fff; border: 1px solid #E3E3E3; border-radius: 8px;
    box-shadow: 0 10px 25px -5px rgba(0,0,0,0.18);
    padding: 8px 4px; z-index: 100;
    min-width: 220px; max-height: 360px; overflow-y: auto;
    display: none;
}
.columns-dropdown.open .columns-popover { display: block; }
.columns-popover .col-row {
    display: flex; align-items: center; gap: 8px;
    padding: 4px 10px; font-size: 12px; cursor: pointer;
    border-radius: 4px;
}
.columns-popover .col-row:hover { background: #EBEEED; }
.columns-popover .col-actions {
    display: flex; gap: 12px; padding: 4px 12px 6px;
    border-bottom: 1px solid #EBEEED; margin-bottom: 4px;
}
.columns-popover .col-actions a {
    color: #2d9cdb; font-size: 11px; cursor: pointer; text-decoration: none;
}
.columns-popover .col-actions a:hover { text-decoration: underline; }

/* 17. SOURCE CHIP */
.src-chip {
    display: inline-flex; align-items: center; gap: 8px;
    padding: 7px 12px; border-radius: 8px; background: #DEEAF4;
    border: 1px solid #CBE5FB; color: #1e7bb4;
    font-size: 12px; font-weight: 600;
}
.src-chip .src-label { color: #176C9E; opacity: 0.7; font-weight: 500; }
.src-chip select {
    border: 1px solid #CBE5FB; background: #fff; color: #1e7bb4;
    border-radius: 6px; padding: 3px 6px; font-size: 11px; font-weight: 600;
}

/* 18. SCROLLBAR */
.custom-scrollbar::-webkit-scrollbar,
.results-table-container::-webkit-scrollbar { width: 8px; height: 8px; }
.custom-scrollbar::-webkit-scrollbar-track,
.results-table-container::-webkit-scrollbar-track { background: #EBEEED; border-radius: 4px; }
.custom-scrollbar::-webkit-scrollbar-thumb,
.results-table-container::-webkit-scrollbar-thumb { background: #C6D0D4; border-radius: 4px; }
.custom-scrollbar::-webkit-scrollbar-thumb:hover,
.results-table-container::-webkit-scrollbar-thumb:hover { background: #8FA1A7; }

/* 19. SPINNER */
@keyframes spin { to { transform: rotate(360deg); } }
.spin { animation: spin 0.8s linear infinite; }

/* 20. TABLE HEADERS */
/* Faint column separator between th cells. rgba white at low alpha reads as
   a subtle vertical line against the brand-navy #0B3140 header used across
   the report family, while staying essentially invisible on any light
   header (where it'd otherwise look like an unwanted rule).
   :last-child is excluded so the rightmost column doesn't render a
   redundant edge. */
th { border-right: 1px solid rgba(255, 255, 255, 0.12); }
th:last-child { border-right: none; }

/* 21. UTILITIES */
.text-muted   { color: #506872; }
.text-primary { color: var(--color-primary); }
.text-success { color: #1B7A46; }
.text-danger  { color: #C43046; }
.text-warning { color: #F69133; }
.fw-bold      { font-weight: 700; }
.text-center  { text-align: center; }
.d-block      { display: block; }
.hidden       { display: none !important; }

/* ============================================================================
   WORKSPACE CHROME (sections 22–33) — promoted from the v1.2 dashboards
   (Production_Scheduling_v1.2, Sales_Dashboard_v1.2) and the summary-report
   family so every report shares one copy. Living showcase:
   Template/Core_Dashboard_Template.htm (Style Guide drawer) and
   Other_NOT_FOR_PRODUCTION/FB_Brand_Mockup.htm.
   Two HEADER idioms coexist: `header` + .hdr-btn (§4 — compact 56px report
   header) and .topbar + .ps-btn (§22/23 — 60px dashboard chrome with tabs).
   Two TABLE tiers coexist: .rpt-table (§29 — compact report table) and
   .tbl-wrap (§30 — roomier dashboard table). Pick per report type.
   ============================================================================ */

/* 22. TOPBAR — dashboard header chrome (60px row + optional .tabs row).
   Crumb over an 800-weight title, optional .subline, actions right. */
.topbar { background: #fff; border-bottom: 1px solid var(--border); padding: 0 22px; flex-shrink: 0; }
.topbar-row1 { display: flex; align-items: center; justify-content: space-between; height: 60px; gap: 12px; }
.title-wrap { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.title-wrap h1 { font-size: 19px; font-weight: 800; letter-spacing: -.01em; margin: 0; line-height: 1.1; color: var(--c-primary); white-space: nowrap; }
.crumb { font-size: 11px; color: var(--c-tertiary); font-weight: 600; text-transform: uppercase; letter-spacing: .06em; }
.subline { font-size: 11.5px; color: var(--c-secondary); white-space: nowrap; }
.top-actions { display: flex; align-items: center; gap: 8px; flex-shrink: 0; flex-wrap: nowrap; }
.search { position: relative; }
.search input { width: 230px; height: 36px; border: 1px solid var(--border); border-radius: var(--r-btn);
    padding: 0 12px 0 34px; font-size: 13px; color: var(--c-primary); background: var(--bg-1);
    outline: none; transition: .15s; font-family: inherit; }
.search input:focus { border-color: var(--fb-blue); background: #fff; box-shadow: 0 0 0 3px rgba(45,156,219,.18); }
.search svg { position: absolute; left: 10px; top: 9px; width: 17px; height: 17px; color: var(--c-tertiary); }

/* 23. PS-BTN — dashboard button family. Named .ps-btn (NOT .btn — §5 owns
   that older family) . Variants: .primary .success .icon .sm .ok .ro .on */
.ps-btn { height: 36px; padding: 0 14px; border-radius: var(--r-btn); border: 1px solid var(--border-strong);
    background: #fff; color: var(--c-secondary); font-size: 13px; font-weight: 600;
    display: inline-flex; align-items: center; gap: 6px; transition: .15s; white-space: nowrap;
    cursor: pointer; font-family: inherit; }
.ps-btn:hover { background: var(--bg-1); border-color: var(--fb-neutral); }
.ps-btn svg { width: 16px; height: 16px; }
.ps-btn.primary { background: var(--fb-blue); border-color: var(--fb-blue-accent); color: #fff; }
.ps-btn.primary:hover { background: var(--fb-blue-accent); }
.ps-btn.success { background: var(--fb-success); border-color: var(--fb-success); color: #fff; }
.ps-btn.success:hover { background: #146C31; border-color: #146C31; }
.ps-btn.icon { width: 36px; padding: 0; justify-content: center; }
.ps-btn.sm { height: 28px; padding: 0 10px; font-size: 12px; }
.ps-btn.sm svg { width: 14px; height: 14px; }
.ps-btn.icon.sm { width: 28px; }
/* .ok / .ro status colours are size-independent (they style the admin
   Users-editing toggle at either .sm or full .ps-btn size). */
.ps-btn.ok { background: var(--acc-sage); border-color: #A9CDBA; color: var(--fb-success); }
.ps-btn.ro { background: var(--acc-maroon-bg); border-color: #D9A4B2; color: #8A1E30; }
.ps-btn.on { background: var(--tint-blue); border-color: var(--tint-blue-2); color: var(--fb-blue); }
.ps-btn:disabled { opacity: .45; cursor: not-allowed; }

/* 24. VIEW TABS — underline tab strip (second .topbar row). */
.tabs { display: flex; gap: 2px; align-items: flex-end; height: 46px; }
.tab { height: 46px; padding: 0 16px; border: none; background: transparent; color: var(--c-secondary);
    font-size: 13.5px; font-weight: 600; display: inline-flex; align-items: center; gap: 7px;
    position: relative; border-bottom: 3px solid transparent; transition: .15s;
    cursor: pointer; font-family: inherit; }
.tab:hover { color: var(--c-primary); }
.tab.active { color: var(--fb-blue); border-bottom-color: var(--fb-blue); }
.tab svg { width: 17px; height: 17px; }
.tab .cnt { font-size: 11px; font-weight: 700; background: var(--bg-2); color: var(--c-secondary);
    border-radius: var(--r-pill); padding: 1px 7px; min-width: 20px; text-align: center; }
.tab.active .cnt { background: var(--tint-blue); color: var(--fb-blue); }

/* 25. FILTER STRIP — always-visible chip bar under the topbar. */
.filterbar { display: flex; align-items: center; gap: 6px; padding: 8px 22px; background: #fff;
    border-bottom: 1px solid var(--border); flex-wrap: wrap; min-height: 44px; flex-shrink: 0; }
.fchip { height: 26px; padding: 0 9px; border-radius: var(--r-pill); border: 1px solid var(--border-strong);
    background: #fff; color: var(--c-secondary); font-size: 11.5px; font-weight: 600;
    display: inline-flex; align-items: center; gap: 5px; transition: .15s; cursor: pointer; font-family: inherit; }
.fchip:hover { background: var(--bg-1); }
.fchip svg { width: 13px; height: 13px; color: var(--c-tertiary); }
.fchip.on { background: var(--tint-blue); border-color: var(--tint-blue-2); color: var(--fb-blue); }
.fchip.on svg { color: var(--fb-blue); }
.filter-sep { width: 1px; height: 18px; background: var(--border-strong); margin: 0 9px; }
.filterbar .spring { flex: 1; }
.grpseg { display: inline-flex; border: 1px solid var(--border-strong); border-radius: var(--r-btn); overflow: hidden; }
.grpseg button { height: 26px; padding: 0 10px; border: none; background: #fff; color: var(--c-secondary);
    font-size: 11.5px; font-weight: 600; border-right: 1px solid var(--border); cursor: pointer; font-family: inherit; }
.grpseg button:last-child { border-right: none; }
.grpseg button.active { background: var(--tint-blue); color: var(--fb-blue); }

/* 26. FDROP — filter-strip dropdown (trigger = .fchip.fdrop-btn, popover
   panel). Single- or multi-select; .fdrop-daterange hosts custom date
   inputs inside a date-preset panel. .fdrop-dot: bare = inline-coloured
   category dot; add .hollow for the ring-that-fills-on-select style. */
.fdrop { position: relative; display: inline-flex; }
.fdrop-btn { gap: 6px; }
.fdrop-caret { transition: transform .15s; }
.fdrop-btn.open .fdrop-caret { transform: rotate(180deg); }
.fdrop-panel { position: absolute; top: calc(100% + 6px); left: 0; z-index: 260; display: none;
    min-width: 200px; max-width: 300px; background: #fff; border: 1px solid var(--border-strong);
    border-radius: var(--r-card); box-shadow: var(--sh2); padding: 6px; }
.fdrop-head { display: flex; align-items: center; justify-content: space-between; gap: 10px;
    padding: 4px 8px 6px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: var(--c-tertiary); }
.fdrop-head a { color: var(--fb-negative); cursor: pointer; text-transform: none; letter-spacing: normal; font-weight: 600; }
.fdrop-head a:hover { text-decoration: underline; }
.fdrop-list { max-height: 280px; overflow-y: auto; display: flex; flex-direction: column; gap: 1px; }
.fdrop-item { display: flex; align-items: center; gap: 8px; padding: 5px 8px; border-radius: 4px;
    font-size: 12px; color: var(--c-primary); cursor: pointer; }
.fdrop-item:hover { background: var(--bg-1); }
.fdrop-item.sel { background: var(--tint-blue); }
.fdrop-item input[type=checkbox] { margin: 0; flex-shrink: 0; width: 14px; height: 14px; accent-color: var(--fb-blue); cursor: pointer; }
.fdrop-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
.fdrop-dot.hollow { border: 1px solid var(--border-strong); }
.fdrop-item.sel .fdrop-dot.hollow { background: var(--fb-blue); border-color: var(--fb-blue); }
.fdrop-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fdrop-empty { padding: 8px; color: var(--c-tertiary); font-size: 12px; text-align: center; }
.fdrop-daterange { display: flex; align-items: center; gap: 6px; padding: 6px 8px 4px; border-top: 1px solid var(--bg-2); margin-top: 4px; }
.fdrop-daterange input[type=date] { height: 28px; border: 1px solid var(--border-strong); border-radius: var(--r-btn);
    font-size: 11.5px; font-family: inherit; color: var(--c-primary); padding: 0 6px; flex: 1; min-width: 0; }
.fdrop-daterange .arrow { color: var(--c-tertiary); font-size: 11px; }

/* 27. SPILL — consolidated status pill. One geometry (matches .stat-badge)
   + one tone set so every status across the suite reads with the same
   colour language: neutral · active · success · caution · critical · blocked. */
.spill { display: inline-flex; align-items: center; gap: 5px; padding: 4px 10px;
    border-radius: var(--r-pill); font-size: 11px; font-weight: 700; line-height: 1.3;
    border: 1px solid; white-space: nowrap; flex-shrink: 0; }
.spill svg { width: 12px; height: 12px; flex-shrink: 0; }
.spill .dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
.spill.neutral  { background: var(--bg-2);          border-color: var(--bg-4);        color: var(--fb-neutral); }
.spill.active   { background: var(--tint-blue);     border-color: var(--tint-blue-2); color: var(--fb-blue-accent); }
.spill.success  { background: var(--acc-sage);      border-color: #A9CDBA;            color: var(--fb-success); }
.spill.caution  { background: var(--acc-orange-bg); border-color: #EBC49B;            color: var(--acc-orange-con); }
.spill.critical { background: var(--acc-maroon-bg); border-color: #D9A4B2;            color: #8A1E30; }
.spill.blocked  { background: var(--acc-purple-bg); border-color: #BBA5EE;            color: var(--acc-purple-con); }

/* 28. KPI TILE — icon-chip stat card (2026-07 decision: replaces the old
   4px left-accent-bar pattern). Anatomy:
     <div class="kpi-tile">                        ← or any card container
       <div class="kpi-chip tone-blue"><svg/></div>
       <div class="kpi-text">
         <div class="kpi-lbl">Open Work Orders</div>
         <div class="kpi-val">42 <span class="kpi-sub">of 60 in view</span>
                                 <span class="kpi-delta">▲4.1%</span></div>
       </div>
     </div>
   The chip carries the tone (tinted square + coloured icon); the VALUE is
   always neutral dark. Use .kpis for the responsive 6/3/2 grid. */
.kpis { display: grid; grid-template-columns: repeat(6, 1fr); gap: 12px; margin-bottom: 16px; }
@media (max-width: 1180px) { .kpis { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 620px)  { .kpis { grid-template-columns: repeat(2, 1fr); } }
.kpi-tile { min-height: 82px; background: #fff; border: 1px solid var(--border); border-radius: var(--r-card);
    box-shadow: var(--sh1); display: flex; align-items: center; gap: 12px; padding: 10px 16px; }
.kpi-chip { width: 40px; height: 40px; border-radius: 10px; display: flex; align-items: center;
    justify-content: center; flex-shrink: 0; }
.kpi-chip svg { width: 20px; height: 20px; }
.kpi-text { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.kpi-lbl { font-size: 11px; font-weight: 600; color: var(--c-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.kpi-val { font-size: 24px; font-weight: 800; letter-spacing: -.02em; line-height: 1; color: var(--c-primary);
    display: flex; align-items: baseline; gap: 7px; }
.kpi-sub { font-size: 11px; color: var(--c-tertiary); font-weight: 500; }
.kpi-delta { font-size: 11.5px; font-weight: 700; }
/* Chip tones — tint background + on-tint icon colour. */
.kpi-chip.tone-blue     { background: var(--tint-blue);     color: var(--fb-blue-accent); }
.kpi-chip.tone-success  { background: var(--acc-sage);      color: var(--fb-success); }
.kpi-chip.tone-warning  { background: var(--acc-orange-bg); color: var(--acc-orange-con); }
.kpi-chip.tone-negative { background: var(--acc-maroon-bg); color: #8A1E30; }
.kpi-chip.tone-purple   { background: var(--acc-purple-bg); color: var(--acc-purple-con); }
.kpi-chip.tone-yellow   { background: var(--acc-yellow-bg); color: var(--acc-yellow-con); }
.kpi-chip.tone-neutral  { background: var(--bg-2);          color: var(--fb-neutral); }

/* 29. RPT-TABLE — the compact "report" table tier (summary reports).
   12px, tight 4px rows, zebra + hover, sortable/drag-reorder navy header.
   Markup keeps id="dataTable" for JS; add class="rpt-table" for styling. */
.rpt-table { border-collapse: collapse; width: 100%; font-size: 12px; table-layout: auto; }
.rpt-table th { background: var(--menu-bg); color: #fff; font-weight: 500;
    padding: 7px 10px; text-align: left; white-space: nowrap;
    cursor: grab; user-select: none; position: sticky; top: 0; z-index: 10; }
.rpt-table th:active { cursor: grabbing; }
.rpt-table th:hover { background: #164A5F; }
.rpt-table th.sort-asc::after  { content: ' \2191'; opacity: 0.8; }
.rpt-table th.sort-desc::after { content: ' \2193'; opacity: 0.8; }
.rpt-table th.col-drag-over { background: #164A5F; border-left: 3px solid var(--tint-blue-2); }
.rpt-table td { padding: 4px 10px; border-bottom: 1px solid var(--border); white-space: nowrap; vertical-align: middle; }
.rpt-table tr:nth-child(even) td { background: var(--bg-1); }
.rpt-table tr:hover td { background: var(--tint-blue) !important; }
.rpt-table .num-cell { text-align: right; font-variant-numeric: tabular-nums; }
/* Totals footer — mirrors the navy header, pinned to the BOTTOM of the scroll
   box so the grand totals stay visible while the body scrolls under it. Uses an
   inset box-shadow for the top rule (a real border can drop out on a sticky cell
   under border-collapse). The hover/zebra overrides keep it navy at all times. */
.rpt-table tfoot td { background: var(--menu-bg); color: #fff; font-weight: 600;
    padding: 7px 10px; white-space: nowrap; position: sticky; bottom: 0; z-index: 11;
    box-shadow: inset 0 2px 0 0 var(--tint-blue-2); }
.rpt-table tfoot td.num-cell { text-align: right; font-variant-numeric: tabular-nums; }
.rpt-table tfoot tr:hover td,
.rpt-table tfoot tr:nth-child(even) td { background: var(--menu-bg) !important; }

/* 30. TBL-WRAP — the roomier "dashboard" table tier (v1.2 dashboards).
   Card wrapper + 13px table with uppercase navy header, 10px rows. */
.tbl-wrap { background: #fff; border: 1px solid var(--border); border-radius: var(--r-card); overflow: auto; box-shadow: var(--sh1); }
.tbl-wrap table { width: 100%; border-collapse: collapse; font-size: 13px; }
.tbl-wrap thead th { background: var(--menu-bg); color: #D5E4E8; text-align: left; font-size: 11px; font-weight: 700;
    text-transform: uppercase; letter-spacing: .05em; padding: 11px 14px; white-space: nowrap; position: sticky; top: 0; z-index: 2; }
.tbl-wrap tbody td { padding: 10px 14px; border-bottom: 1px solid var(--bg-2); white-space: nowrap; }
.tbl-wrap tbody tr:hover { background: var(--bg-1); }
.tbl-wrap tbody tr:last-child td { border-bottom: none; }
.tbl-wrap td.num { text-align: right; font-family: var(--mono); }

/* 31. ROW LINKS — interactive record links inside tables/cards. */
.row-link, .order-link { color: var(--link); cursor: pointer; text-decoration: none; font-weight: 600; }
.row-link:hover, .order-link:hover { text-decoration: underline; color: var(--link-hover); }

/* 32. MULTI-SELECT (.ms-*) — the widget FBLib.Common.MultiSelect.create()
   renders into. Canonical markup lives in fb-lib's MULTI-SELECT doc block. */
.ms-container { position: relative; }
.ms-trigger { display: flex; align-items: center; flex-wrap: nowrap; gap: 3px;
    border: 1px solid var(--border); border-radius: 6px; padding: 3px 8px;
    background: #fff; height: 30px; overflow: hidden; cursor: pointer; font-size: 12px; }
.ms-trigger:hover { border-color: var(--c-tertiary); }
.ms-tag { background: var(--tint-blue); color: var(--link-hover); padding: 1px 5px; border-radius: 3px;
    font-size: 11px; display: flex; align-items: center; gap: 2px; white-space: nowrap; }
.ms-tag-x { cursor: pointer; font-weight: bold; }
.ms-placeholder { color: var(--c-tertiary); }
.ms-dropdown { position: absolute; z-index: 500; top: calc(100% + 2px); left: 0; right: 0; min-width: 220px;
    background: #fff; border: 1px solid var(--border-strong); border-radius: 6px;
    box-shadow: var(--sh2); display: flex; flex-direction: column; max-height: 280px; }
.ms-dropdown.hidden { display: none; }
.ms-search { padding: 6px 8px; border-bottom: 1px solid var(--bg-2); }
.ms-search input { width: 100%; border: 1px solid var(--border-strong); border-radius: 4px;
    padding: 4px 8px; font-size: 12px; outline: none; font-family: inherit; }
.ms-actions { padding: 3px 10px; border-bottom: 1px solid var(--bg-2); display: flex; gap: 10px; font-size: 11px; }
.ms-actions span { color: var(--link); cursor: pointer; }
.ms-actions span:hover { text-decoration: underline; }
.ms-list { overflow-y: auto; flex: 1; }
.ms-item { display: flex; align-items: center; gap: 8px; padding: 5px 10px; cursor: pointer; font-size: 12px; }
.ms-item:hover { background: var(--tint-blue); }
.ms-sep { height: 1px; background: var(--border); margin: 4px 0; }
.ms-group-hdr { padding: 4px 10px 2px; font-size: 10px; font-weight: 600; color: var(--c-secondary);
    text-transform: uppercase; letter-spacing: 0.05em; pointer-events: none; }
.ms-empty { padding: 12px; color: var(--c-tertiary); font-size: 12px; text-align: center; }

/* 33. MISC SHARED BITS */
/* Square close button for modals/panels (28px base; .lg = 32px). */
.close-x { width: 28px; height: 28px; border-radius: var(--r-btn); border: 1px solid var(--border); background: #fff;
    display: flex; align-items: center; justify-content: center; color: var(--c-secondary); cursor: pointer; flex-shrink: 0; }
.close-x:hover { background: var(--bg-1); }
.close-x.lg { width: 32px; height: 32px; }
/* Status badges — numeric Fishbowl status-code tones shared by the summary
   reports. Re-aligned (2026-07) from the legacy Tailwind palette onto the
   brand accent pairs so they speak the same colour language as .spill:
   entered=neutral · issued=blue tint · in-progress=orange · picked/
   fulfilled=sage · closed-short=yellow · voided=maroon · cancelled=purple ·
   expired=greyed maroon. */
.badge { display: inline-block; padding: 1px 7px; border-radius: 3px; font-size: 11px; font-weight: 500; }
.b10 { background: var(--bg-2);          color: var(--fb-neutral); }      /* Estimate / Entered */
.b20 { background: var(--tint-blue);     color: var(--fb-blue-accent); }  /* Issued */
.b25 { background: var(--acc-orange-bg); color: var(--acc-orange-con); }  /* In Progress / Partial */
.b40 { background: var(--acc-sage);      color: var(--fb-success); }      /* Picked */
.b60 { background: var(--acc-sage);      color: var(--fb-success); }      /* Fulfilled */
.b70 { background: var(--acc-yellow-bg); color: var(--acc-yellow-con); }  /* Closed Short */
.b80 { background: var(--acc-maroon-bg); color: #8A1E30; }                /* Voided */
.b85 { background: var(--acc-purple-bg); color: var(--acc-purple-con); }  /* Cancelled */
.b90 { background: var(--bg-3);          color: var(--acc-maroon-con); }  /* Expired */
/* Standard loading overlay — pair with the .spin keyframes (§19). */
.loading-overlay { position: absolute; inset: 0; z-index: 30; display: flex; flex-direction: column;
    align-items: center; justify-content: center; gap: 10px; background: rgba(247,247,247,.85); }
.loading-overlay .lo-label { font-size: 13px; color: var(--c-secondary); font-weight: 500; }

/* 34. PIVOT — the shared pivot config strip + cross-tab table used by the
   four summary reports (PO/SO/Receiving/PartActivity). Promoted 2026-07
   from four byte-identical local copies. Markup keeps ids (JS targets) and
   adds classes: .pivot-bar, .pivot-overflow, .pivot-table, .pivot-drill-body.
   Child classes (.pv-group/.pv-totals/.pv-swap/.pv-total/.pv-empty/
   .pv-totals-row and PartActivity's opt-in .pv-pos/.pv-neg) are unchanged. */
.pivot-bar {
    display: none; background: var(--bg-1); border-bottom: 1px solid var(--border);
    padding: 10px 20px; flex-shrink: 0; flex-wrap: wrap; gap: 10px 16px;
    align-items: center; font-size: 12px;
}
.pivot-bar.open { display: flex; }
.pivot-bar .pv-group {
    display: inline-flex; align-items: center; gap: 6px;
    font-size: 11px; font-weight: 600; color: var(--c-secondary);
    text-transform: uppercase; letter-spacing: 0.04em;
}
.pivot-bar select {
    padding: 4px 8px; font-size: 12px; border: 1px solid var(--border-strong); border-radius: 6px;
    background: #fff; color: var(--c-primary); font-family: inherit;
    text-transform: none; letter-spacing: 0; font-weight: 400;
}
.pivot-bar .pv-totals {
    display: inline-flex; align-items: center; gap: 6px;
    font-size: 11px; color: var(--c-secondary); font-weight: 500;
    text-transform: none; letter-spacing: 0;
}
.pivot-bar .pv-totals input { margin: 0; }
.pivot-bar button.pv-swap {
    padding: 4px 10px; font-size: 11px; border: 1px solid var(--border-strong);
    background: #fff; color: var(--c-secondary); border-radius: 6px; cursor: pointer; font-family: inherit;
}
.pivot-bar button.pv-swap:hover { background: var(--bg-2); border-color: var(--c-tertiary); }

.pivot-table { border-collapse: collapse; width: 100%; font-size: 12px; table-layout: auto; }
.pivot-table th, .pivot-table td { padding: 4px 10px; border-bottom: 1px solid var(--border); white-space: nowrap; vertical-align: middle; }
.pivot-table thead th {
    background: var(--menu-bg); color: #fff; font-weight: 500;
    text-align: right; position: sticky; top: 0; z-index: 12;
}
.pivot-table thead th:first-child { text-align: left; left: 0; z-index: 13; }
.pivot-table tbody tr.pv-totals-row { font-weight: 700; background: var(--bg-2); }
.pivot-table tbody td { text-align: right; font-variant-numeric: tabular-nums; cursor: pointer; }
.pivot-table tbody td:first-child {
    text-align: left; font-variant-numeric: normal;
    background: var(--bg-1); font-weight: 600; color: var(--c-primary);
    position: sticky; left: 0; z-index: 5; cursor: default;
}
.pivot-table tbody td.pv-total { background: var(--bg-2); font-weight: 700; color: var(--c-primary); }
.pivot-table tbody td.pv-empty { color: var(--border-strong); cursor: default; }
/* Two hover intensities on purpose: row hover = tint-blue, the hovered CELL
   itself = the stronger tint-blue-2 (preserves the legacy #eff6ff/#dbeafe
   distinction on the brand tints). */
.pivot-table tbody tr:hover td:not(:first-child):not(.pv-total) { background: var(--tint-blue); }
.pivot-table tbody td:hover:not(:first-child):not(.pv-total):not(.pv-empty) { background: var(--tint-blue-2) !important; }
/* Signed-measure colouring (opt-in — PartActivity toggles body.pv-signed-measure). */
body.pv-signed-measure .pivot-table tbody td.pv-pos { color: var(--fb-success); }
body.pv-signed-measure .pivot-table tbody td.pv-neg { color: var(--fb-negative); }

.pivot-overflow {
    display: none; padding: 8px 14px;
    background: var(--acc-yellow-bg); border-bottom: 1px solid var(--acc-yellow);
    color: var(--acc-yellow-con); font-size: 12px; font-weight: 500;
}
.pivot-overflow.show { display: block; }

.pivot-drill-body { max-height: 70vh; overflow: auto; padding: 0; }
.pivot-drill-body table { border-collapse: collapse; width: 100%; font-size: 12px; }
.pivot-drill-body th {
    background: var(--menu-bg); color: #fff; font-weight: 500;
    padding: 6px 10px; text-align: left; white-space: nowrap;
    position: sticky; top: 0; z-index: 5;
}
.pivot-drill-body td {
    padding: 4px 10px; border-bottom: 1px solid var(--border);
    white-space: nowrap; vertical-align: middle;
}
.pivot-drill-body tr:nth-child(even) td { background: var(--bg-1); }
.pivot-drill-body td.num-cell { text-align: right; font-variant-numeric: tabular-nums; }
